-- Per-unit EI mandate. Organization owner/admin manages autonomy boundaries for each clinic unit.
create table private.reda_unit_ei_mandates(unit_id uuid primary key,organization_id uuid not null,automatic_progression boolean not null default false,automatic_regression boolean not null default false,max_autonomous_steps integer not null default 3 check(max_autonomous_steps between 1 and 20),revision integer not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),foreign key(unit_id,organization_id)references public.reda_units(id,organization_id));
create table private.reda_unit_ei_mandate_events(id bigint generated always as identity primary key,unit_id uuid not null,organization_id uuid not null,actor_id uuid not null references auth.users(id),before_state jsonb not null,after_state jsonb not null,created_at timestamptz not null default now(),foreign key(unit_id,organization_id)references public.reda_units(id,organization_id));
create index reda_unit_ei_events on private.reda_unit_ei_mandate_events(organization_id,unit_id,created_at desc);alter table private.reda_unit_ei_mandates enable row level security;alter table private.reda_unit_ei_mandate_events enable row level security;revoke all on private.reda_unit_ei_mandates,private.reda_unit_ei_mandate_events from public,anon,authenticated;
create function private.reda_unit_ei_settings(p_unit uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare actor uuid:=private.reda_live_actor();org uuid:=private.reda_request_organization();begin if not private.reda_is_clinician_aal2() or not private.reda_unit_allowed(p_unit)then raise exception using errcode='42501',message='Enheten är inte tillgänglig.';end if;return coalesce((select to_jsonb(m) from private.reda_unit_ei_mandates m where m.unit_id=p_unit and m.organization_id=org),jsonb_build_object('unit_id',p_unit,'organization_id',org,'automatic_progression',false,'automatic_regression',false,'max_autonomous_steps',3,'revision',0));end$$;
create function private.reda_save_unit_ei_settings(p_unit uuid,p_revision integer,p_progression boolean,p_regression boolean,p_max_steps integer)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=private.reda_live_actor();org uuid:=private.reda_request_organization();before jsonb;after jsonb;begin if not private.reda_is_clinician_aal2() or not private.reda_can_manage_units(org,actor)then raise exception using errcode='42501',message='Organisationens adminbehörighet och MFA krävs.';end if;if p_max_steps not between 1 and 20 then raise exception using errcode='22023',message='Kontrollera autonomigränsen.';end if;before=private.reda_unit_ei_settings(p_unit);if p_revision<>(before->>'revision')::int then raise exception using errcode='40001',message='EI-mandatet har ändrats. Uppdatera innan du sparar.';end if;insert into private.reda_unit_ei_mandates(unit_id,organization_id,automatic_progression,automatic_regression,max_autonomous_steps,updated_by)values(p_unit,org,p_progression,p_regression,p_max_steps,actor)on conflict(unit_id)do update set automatic_progression=excluded.automatic_progression,automatic_regression=excluded.automatic_regression,max_autonomous_steps=excluded.max_autonomous_steps,revision=reda_unit_ei_mandates.revision+1,updated_by=actor,updated_at=now();after=private.reda_unit_ei_settings(p_unit);insert into private.reda_unit_ei_mandate_events(unit_id,organization_id,actor_id,before_state,after_state)values(p_unit,org,actor,before,after);return after;end$$;
create function public.reda_unit_ei_settings(p_unit uuid)returns jsonb language sql stable security invoker set search_path='' as $$select private.reda_unit_ei_settings(p_unit)$$;create function public.reda_save_unit_ei_settings(p_unit uuid,p_revision integer,p_progression boolean,p_regression boolean,p_max_steps integer)returns jsonb language sql security invoker set search_path='' as $$select private.reda_save_unit_ei_settings(p_unit,p_revision,p_progression,p_regression,p_max_steps)$$;
revoke all on function private.reda_unit_ei_settings(uuid),private.reda_save_unit_ei_settings(uuid,integer,boolean,boolean,integer),public.reda_unit_ei_settings(uuid),public.reda_save_unit_ei_settings(uuid,integer,boolean,boolean,integer) from public,anon,authenticated;grant execute on function private.reda_unit_ei_settings(uuid),private.reda_save_unit_ei_settings(uuid,integer,boolean,boolean,integer),public.reda_unit_ei_settings(uuid),public.reda_save_unit_ei_settings(uuid,integer,boolean,boolean,integer) to authenticated;
